const fallback=[{id:1,name:'MacBook Air 13 M3 2024',brand:'Apple',category:'Laptop',price:25990000,original_price:27990000,stock:12,image_url:'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=900&q=85',rating:4.9,is_featured:1},{id:2,name:'iPhone 16 Pro 256GB',brand:'Apple',category:'Điện thoại',price:28990000,original_price:30990000,stock:8,image_url:'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=900&q=85',rating:4.8,is_featured:1},{id:3,name:'ASUS ROG Zephyrus G14',brand:'ASUS',category:'Laptop',price:42990000,original_price:45990000,stock:5,image_url:'https://images.unsplash.com/photo-1593642632823-8f785ba67e45?auto=format&fit=crop&w=900&q=85',rating:4.7},{id:4,name:'Sony WH-1000XM5',brand:'Sony',category:'Phụ kiện',price:7990000,original_price:8990000,stock:18,image_url:'https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=900&q=85',rating:4.9},{id:5,name:'iPad Air M2 11 inch',brand:'Apple',category:'Máy tính bảng',price:16990000,original_price:17990000,stock:10,image_url:'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=900&q=85',rating:4.8},{id:6,name:'Dell UltraSharp 27 4K',brand:'Dell',category:'Màn hình',price:14990000,original_price:16990000,stock:7,image_url:'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=900&q=85',rating:4.6}];
