const socialLinks=[{name:'Facebook',href:import.meta.env.VITE_SOCIAL_FACEBOOK_URL?.trim()||'https://www.facebook.com/',Icon:Facebook},{name:'Instagram',href:import.meta.env.VITE_SOCIAL_INSTAGRAM_URL?.trim()||'https://www.instagram.com/',Icon:Instagram},{name:'TikTok',href:import.meta.env.VITE_SOCIAL_TIKTOK_URL?.trim()||'https://www.tiktok.com/',Icon:ExternalLink}];
